DASHBOARD_SPA_HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Automation Console</title><style>
:root{--brand:#635bff;--ink:#172033;--muted:#667085;--line:#e6e9f1;--bg:#f7f8fc;--card:#fff;--ok:#057a55;--bad:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,ui-sans-serif,system-ui,sans-serif}.app{min-height:100vh;display:grid;grid-template-columns:244px 1fr}.side{background:#161d2f;color:#e8ecf7;padding:24px 14px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;padding:0 10px 27px;font-weight:750;font-size:16px}.mark{background:linear-gradient(135deg,#8b84ff,#5549e7);width:29px;height:29px;border-radius:9px;display:grid;place-items:center}.side small{padding:0 10px;color:#8e99b0;text-transform:uppercase;letter-spacing:.1em;font-size:10px}.nav{margin-top:10px}.nav button{border:0;background:transparent;color:#b5bfd4;width:100%;text-align:left;padding:11px 12px;border-radius:8px;cursor:pointer;font:inherit;margin:2px 0}.nav button.active,.nav button:hover{background:#27334f;color:#fff}.bottom{margin-top:auto;border-top:1px solid #2e3850;padding:18px 10px 2px;font-size:12px;color:#aab4c8}.online{color:#52d49a}.main{max-width:1050px;width:100%;padding:34px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.top h1{font-size:25px;letter-spacing:-.035em;margin:0 0 5px}.top p{margin:0;color:var(--muted)}.key{display:flex;gap:8px}.card{background:var(--card);border:1px solid var(--line);border-radius:15px;box-shadow:0 10px 34px #2430520b}.card-head{padding:19px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.card-head h2{font-size:15px;margin:0}.card-body{padding:22px}.view{display:none}.view.active{display:block}.field{margin-bottom:16px}.field label{display:block;font-weight:680;font-size:12px;margin-bottom:7px;color:#344054}.field small{float:right;color:var(--muted);font-weight:400}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}input,textarea,button{font:inherit}input,textarea{width:100%;border:1px solid #d8ddea;border-radius:8px;padding:10px;outline:0;color:var(--ink)}textarea{min-height:83px;resize:vertical}input:focus,textarea:focus{border-color:#908aff;box-shadow:0 0 0 3px #635bff15}.button{border:0;border-radius:8px;padding:9px 12px;background:var(--brand);color:#fff;font-weight:650;cursor:pointer}.button.outline{background:#fff;border:1px solid #d8ddea;color:#344054}.button.danger{color:var(--bad)}.hint{font-size:12px;color:var(--muted);line-height:1.45;margin:6px 0 0}.jobs{padding:2px 22px}.job{border-bottom:1px solid var(--line);padding:17px 0}.job:last-child{border:0}.job-top,.job-foot{display:flex;justify-content:space-between;gap:14px;align-items:center}.name{font-weight:720}.meta,.detail{color:var(--muted);font-size:12px;margin-top:4px}.prompt{color:#475467;line-height:1.45;margin:11px 0}.actions{display:flex;gap:6px}.actions button{padding:6px 8px;font-size:12px}.badge{font-size:11px;font-weight:700;padding:4px 8px;border-radius:99px}.live{background:#ecfdf3;color:#067647}.off{background:#f2f4f7;color:#475467}.failed{background:#fef3f2;color:#b42318}.empty{text-align:center;color:var(--muted);padding:48px 10px}.empty b{display:block;color:#344054;margin-bottom:5px}.log{padding:12px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px}.log:last-child{border:0}.log p{margin:0;font-size:13px}.log time{font-size:11px;color:var(--muted);white-space:nowrap}.toast{position:fixed;right:20px;bottom:20px;background:#172033;color:#fff;padding:11px 14px;border-radius:8px;opacity:0;transition:.2s}.toast.show{opacity:1}@media(max-width:720px){.app{grid-template-columns:1fr}.side{padding:13px;flex-direction:row;align-items:center}.brand{padding:0}.side small,.bottom{display:none}.nav{display:flex;margin:0 0 0 auto}.nav button{width:auto}.main{padding:23px 15px}.top{display:block}.key{margin-top:15px}.two{grid-template-columns:1fr}.job-top,.job-foot{align-items:flex-start;flex-direction:column}.actions{align-self:flex-end}}
</style></head><body><div class="app"><aside class="side"><div class="brand"><span class="mark">✦</span>Automation Console</div><small>Workspace</small><nav class="nav"><button class="active" data-view="create" onclick="showView('create')">＋ Create automation</button><button data-view="schedules" onclick="showView('schedules')">▣ My schedules <span id="side-count"></span></button></nav><div class="bottom"><span class="online">●</span> Local scheduler running</div></aside><main class="main"><header class="top"><div><h1 id="page-title">Create automation</h1><p id="page-subtitle">Schedule a landing page to build and publish automatically.</p></div><div class="key"><input id="key" type="password" placeholder="Control-panel API key"><button class="button outline" onclick="connect()">Connect</button></div></header><section id="create" class="view active"><div class="card"><div class="card-head"><h2>Automation details</h2><span id="connection" class="meta">Not connected</span></div><form class="card-body" onsubmit="createJob(event)"><div class="field"><label>Automation name</label><input id="name" required placeholder="Daily product launch page"></div><div class="two"><div class="field"><label>Schedule <small>cron</small></label><input id="cron" required value="0 9 * * *"></div><div class="field"><label>Timezone</label><input disabled value="Configured server timezone"></div></div><div class="field"><label>Idea / instructions</label><textarea id="prompt" required placeholder="Describe the landing page you want Lovable to create..." ></textarea><p class="hint">The saved idea and references are sent directly to Lovable when the schedule runs.</p></div><div class="field"><label>Reference sites <small>one URL per line</small></label><textarea id="refs" placeholder="https://example.com"></textarea></div><div class="two"><div class="field"><label>Image URLs <small>optional</small></label><textarea id="images" placeholder="https://..."></textarea></div><div class="field"><label>Links to include <small>optional</small></label><textarea id="links" placeholder="https://..."></textarea></div></div><button class="button" type="submit">Create automation</button></form></div></section><section id="schedules" class="view"><div class="card"><div class="card-head"><h2>My schedules</h2><button class="button outline" onclick="refreshAll()">Refresh</button></div><div class="jobs" id="jobs"><div class="empty"><b>No schedules loaded</b>Connect with your API key to view them.</div></div></div><div class="card" style="margin-top:20px"><div class="card-head"><h2>Run activity</h2><button class="button outline" onclick="loadLogs()">Refresh</button></div><div class="jobs" id="logs"><div class="empty"><b>No activity yet</b>Logs appear whenever a job runs.</div></div></div></section></main></div><div id="toast" class="toast"></div><script>
const el=id=>document.getElementById(id),lines=id=>el(id).value.split('\n').map(x=>x.trim()).filter(Boolean);let jobs={};const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));function headers(){return{'Authorization':'Bearer '+localStorage.apiKey,'Content-Type':'application/json'}}function toast(s){el('toast').textContent=s;el('toast').classList.add('show');setTimeout(()=>el('toast').classList.remove('show'),2500)}function showView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));el('page-title').textContent=id==='create'?'Create automation':'My schedules';el('page-subtitle').textContent=id==='create'?'Schedule a landing page to build and publish automatically.':'Manage runs, status, and local activity.';location.hash=id;if(id==='schedules')refreshAll()}function connect(){localStorage.apiKey=el('key').value;refreshAll()}async function req(path,opt={}){let r=await fetch(path,{...opt,headers:headers()});if(!r.ok){let b=await r.json().catch(()=>({}));throw Error(b.detail||'Request failed')}return r.status===204?null:r.json()}async function refreshAll(){await Promise.all([loadJobs(),loadLogs()])}async function loadJobs(){if(!localStorage.apiKey)return;try{let data=await req('/automation/jobs');jobs=Object.fromEntries(data.map(j=>[j.id,j]));el('side-count').textContent=data.length?'('+data.length+')':'';el('connection').textContent='Connected';el('connection').style.color='var(--ok)';el('jobs').innerHTML=data.length?data.map(jobView).join(''):`<div class="empty"><b>No automations yet</b>Create one from the sidebar.</div>`}catch(e){el('connection').textContent='Connection failed';el('connection').style.color='var(--bad)';toast(e.message)}}function jobView(j){let cls=j.last_status==='failed'?'failed':j.enabled?'live':'off';let txt=j.last_status==='failed'?'Failed':j.enabled?'Enabled':'Paused';return `<article class="job"><div class="job-top"><div><div class="name">${esc(j.name)}</div><div class="meta">${esc(j.cron)} · ${esc(j.last_run_at||'Never run')}</div></div><span class="badge ${cls}">${txt}</span></div><p class="prompt">${esc(j.prompt)}</p><div class="job-foot"><span class="detail">${esc(j.last_detail||'Ready to run')}</span><div class="actions"><button class="button outline" onclick="toggle('${j.id}')">${j.enabled?'Pause':'Enable'}</button><button class="button outline" onclick="runNow('${j.id}')">Run now</button><button class="button outline danger" onclick="removeJob('${j.id}')">Delete</button></div></div></article>`}async function createJob(e){e.preventDefault();try{await req('/automation/jobs',{method:'POST',body:JSON.stringify({name:el('name').value,cron:el('cron').value,prompt:el('prompt').value,reference_sites:lines('refs'),images:lines('images'),urls_to_include:lines('links'),enabled:true})});e.target.reset();el('cron').value='0 9 * * *';toast('Automation created');showView('schedules')}catch(e){toast(e.message)}}async function toggle(id){let j={...jobs[id],enabled:!jobs[id].enabled};['id','last_run_at','last_status','last_detail'].forEach(k=>delete j[k]);try{await req('/automation/jobs/'+id,{method:'PUT',body:JSON.stringify(j)});refreshAll()}catch(e){toast(e.message)}}async function runNow(id){try{await req('/automation/jobs/'+id+'/run',{method:'POST'});toast('Run queued');loadLogs()}catch(e){toast(e.message)}}async function removeJob(id){if(!confirm('Delete this automation?'))return;try{await req('/automation/jobs/'+id,{method:'DELETE'});toast('Automation deleted');refreshAll()}catch(e){toast(e.message)}}async function loadLogs(){if(!localStorage.apiKey)return;try{let data=await req('/automation/logs');el('logs').innerHTML=data.length?data.map(x=>`<article class="log"><p>${esc(x.message)}</p><time>${esc(x.timestamp)}</time></article>`).join(''):`<div class="empty"><b>No activity yet</b>Logs appear whenever a job runs.</div>`}catch(e){}}el('key').value=localStorage.apiKey||'';let start=location.hash.slice(1);if(start==='schedules')showView('schedules');if(localStorage.apiKey)refreshAll();setInterval(()=>{if(location.hash==='#schedules')refreshAll()},5000);
</script></body></html>"""
